// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 1, 1 ether);

        address receiver = address(uint160(uint256(keccak256(abi.encodePacked(caller, amount, block.timestamp)))));
        if (receiver == address(0)) receiver = address(1);
        if (receiver == caller) receiver = address(uint160(uint256(keccak256(abi.encodePacked(receiver, "x")))));

        vm.deal(address(c), 1 ether);

        bool ok;
        vm.prank(caller);
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == address(this)));
    }
}
